import{_ as t,o as e,c as o,a4 as r}from"./chunks/framework.CzJ_HCFe.js";const u=JSON.parse('{"title":"04 · User-Facing Features","description":"","frontmatter":{},"headers":[],"relativePath":"reference/04-user-facing-features.md","filePath":"reference/04-user-facing-features.md","lastUpdated":1787887572000}'),s={name:"reference/04-user-facing-features.md"};function d(n,a,i,c,l,g){return e(),o("div",null,[...a[0]||(a[0]=[r(`<h1 id="_04-·-user-facing-features" tabindex="-1">04 · User-Facing Features <a class="header-anchor" href="#_04-·-user-facing-features" aria-label="Permalink to &quot;04 · User-Facing Features&quot;">​</a></h1><p>Three surfaces, all built from the same engine output:</p><ol><li><strong>MCP server</strong> — 17 tools (<code>mcp-server-panchangam</code> on PyPI)</li><li><strong>ICS calendar feeds</strong> — 22 cities × 3 systems, on GitHub Pages</li><li><strong>Landing page</strong> — <code>panchangam.astrochaganti.com</code></li></ol><hr><h2 id="_1-mcp-server-—-17-tools" tabindex="-1">1. MCP server — 17 tools <a class="header-anchor" href="#_1-mcp-server-—-17-tools" aria-label="Permalink to &quot;1. MCP server — 17 tools&quot;">​</a></h2><p>FastMCP server (<a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/telugu_panchangam/mcp/server.py" target="_blank" rel="noreferrer"><code>mcp/server.py</code></a>), with decorator-registered tools wrapping logic in <code>mcp/tools.py</code>. Every tool returns a <strong>JSON string</strong>; failures return <code>{&quot;error&quot;: &quot;…&quot;}</code>.</p><p><strong>Location resolution</strong> (<code>mcp/location.py</code>): a free-text <code>city</code> resolves first against the 22 pre-configured <code>CITIES</code> (instant, no network); unknown names fall back to Nominatim/OpenStreetMap geocoding (10 s timeout) with timezone via <code>timezonefinder</code>. You can also pass <code>latitude</code>/<code>longitude</code>/<code>timezone</code> directly to skip lookup entirely.</p><p><strong>Ayanamsa</strong>: <code>get_panchangam</code>, <code>get_panchangam_range</code>, <code>get_graha_positions</code>, <code>get_gochara</code>, <code>get_rasi_phalalu</code>, <code>get_rashi_ingresses</code>, <code>find_muhurta</code> accept <code>ayanamsa = lahiri | raman | krishnamurti | true_chitrapaksha</code> (default <code>lahiri</code>). SS/Vakya accept it for symmetry but ignore it.</p><h3 id="per-day-single-date" tabindex="-1">Per-day (single date) <a class="header-anchor" href="#per-day-single-date" aria-label="Permalink to &quot;Per-day (single date)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th><th>Key params</th></tr></thead><tbody><tr><td><strong><code>get_panchangam</code></strong></td><td>Full day: 5 angas, sky, all windows, Choghadiya, flags, 1.9.0 timing fields</td><td><code>date, city, system, [lat/lon/tz], ayanamsa</code></td></tr><tr><td><strong><code>get_muhurta</code></strong></td><td>Lighter: just the auspicious/inauspicious windows + timing fields (no anga names/sky/Choghadiya)</td><td><code>date, city, system, [lat/lon/tz]</code></td></tr><tr><td><strong><code>get_panchanga_shuddhi</code></strong></td><td>Five-limb purity verdict (Sarva Shuddha → Sarva Ashuddha) + per-limb reason</td><td><code>date, city, system, [lat/lon/tz]</code></td></tr><tr><td><strong><code>get_daily_horas</code></strong></td><td>24 planetary hours (12 day from sunrise + 12 night), weekday-lord sequence</td><td><code>date, city, system, [lat/lon/tz]</code></td></tr><tr><td><strong><code>get_lagna_transitions</code></strong></td><td>Ascendant sign boundaries across the day</td><td><code>date, city, system, [lat/lon/tz]</code></td></tr></tbody></table><h3 id="planning-across-days" tabindex="-1">Planning across days <a class="header-anchor" href="#planning-across-days" aria-label="Permalink to &quot;Planning across days&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th><th>Key params</th></tr></thead><tbody><tr><td><strong><code>get_panchangam_range</code></strong></td><td>Compact per-day summary over a range (≤31 days)</td><td><code>start_date, end_date, city, system, ayanamsa</code></td></tr><tr><td><strong><code>get_special_days</code></strong></td><td>Festivals, Ekadashi/Amavasya/Pournami/Pradosham, Sankranti, eclipses in a month</td><td><code>year, month, city, system</code></td></tr><tr><td><strong><code>find_muhurta</code></strong></td><td><strong>Ranked auspicious slots</strong> over coming days, activity-aware, every slot with reasons + tier; hard-avoids doshas</td><td><code>start_date, days(≤14), activity, city, system, janma_nakshatras, janma_rasis, janma_lagnas, chandra_mode, travel_direction, ayanamsa</code></td></tr><tr><td><strong><code>find_tarabalam_days</code></strong></td><td>Days favourable for 1–4 people by birth star (+ optional rasi for Chandrabalam)</td><td><code>janma_nakshatras[1-4], start_date, days(≤60), city, system, janma_rasis, chandra_mode</code></td></tr></tbody></table><h3 id="sky-event-calendars-range" tabindex="-1">Sky-event calendars (range) <a class="header-anchor" href="#sky-event-calendars-range" aria-label="Permalink to &quot;Sky-event calendars (range)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th><th>Key params</th></tr></thead><tbody><tr><td><strong><code>get_combustion_calendar</code></strong></td><td>Asta/Udaya (combustion entry/exit) for Mercury/Venus/Mars/Jupiter/Saturn (≤366 days)</td><td><code>start_date, end_date, city, [planets]</code></td></tr><tr><td><strong><code>get_graha_yuddha</code></strong></td><td>Planetary-war periods — winner/loser, timing UTC, min separation (≤366 days)</td><td><code>start_date, end_date, [planets]</code></td></tr><tr><td><strong><code>get_rashi_ingresses</code></strong></td><td>All sign-change events for the classical planets (≤366 days)</td><td><code>start_date, end_date, [planets], ayanamsa</code></td></tr><tr><td><strong><code>get_eclipse_calendar</code></strong></td><td>Solar &amp; lunar eclipses, per-city visibility, Sutak (≤730 days)</td><td><code>start_date, end_date, city</code></td></tr></tbody></table><h3 id="gochara-personal-transits" tabindex="-1">Gochara &amp; personal transits <a class="header-anchor" href="#gochara-personal-transits" aria-label="Permalink to &quot;Gochara &amp; personal transits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th><th>Key params</th></tr></thead><tbody><tr><td><strong><code>get_graha_positions</code></strong></td><td>All 9 grahas at sunrise — rasi, nakshatra, pada, retrograde, next-rasi date</td><td><code>date, city, ayanamsa</code></td></tr><tr><td><strong><code>get_gochara</code></strong></td><td>Transit verdicts from a janma rasi — houses, vedha, Sade Sati / Ashtama Shani</td><td><code>date, janma_rasi, city, ayanamsa</code></td></tr><tr><td><strong><code>get_rasi_phalalu</code></strong></td><td>Deterministic daily reading rendered from gochara + chandrabalam + tarabalam</td><td><code>date, janma_rasi, [janma_nakshatra], city, ayanamsa</code></td></tr></tbody></table><h3 id="utility" tabindex="-1">Utility <a class="header-anchor" href="#utility" aria-label="Permalink to &quot;Utility&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><strong><code>list_supported_cities</code></strong></td><td>The 22 pre-configured cities with lat/lon/timezone</td></tr></tbody></table><blockquote><p><strong>17 tools total.</strong> Grouping mirrors the <a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/README_PYPI.md" target="_blank" rel="noreferrer">README_PYPI tool table</a>; this doc adds the parameter and return-shape detail. Full per-field return shapes were mapped during this doc&#39;s generation — see <code>mcp/tools.py</code> for the authoritative serializers.</p></blockquote><hr><h2 id="_2-ics-calendar-feeds" tabindex="-1">2. ICS calendar feeds <a class="header-anchor" href="#_2-ics-calendar-feeds" aria-label="Permalink to &quot;2. ICS calendar feeds&quot;">​</a></h2><p><strong>What:</strong> one all-day event per day, full panchangam in the description. Festival days get 🪔 in the title; other special days (Ekadashi/Amavasya/Pournami/ Pradosham/Sankranti/eclipse) get ⚡.</p><p><strong>Each event&#39;s description</strong> (<code>generators/ics.py</code>): metadata (Samvatsara/Maasam/Paksham/Vaaram, ayanam/rituvu, signs), the five angas with HH:MM(±1) bounds, sky markers, auspicious &amp; inauspicious windows, daytime <strong>and</strong> night Choghadiya, eclipse + Sutak, special yogas, and a specials summary.</p><p><strong>Dense vs variant feeds:</strong></p><ul><li>Dense (default, <code>variant_label=&#39;&#39;</code>): every day, full description.</li><li><strong>Variant feeds</strong> (<code>generators/anga_variants.py</code>): Ekadashi-only, Festivals-only, Moon-Cycles (Pournami+Amavasya) — pure filters that reuse <code>ICSGenerator</code>, so format/metadata never drift. <em>Built but not yet deployed — a deliberate follow-up (see <a href="./06-roadmap-and-backlog">roadmap</a>).</em></li></ul><p><strong>Generation</strong> (<code>generate.py</code>): <code>generate_feeds(out, start, end, systems, cities)</code> precomputes eclipses once, then loops systems × cities × days → <code>{city_slug}-{system}.ics</code>. <strong>22 cities × 3 systems = 66 feeds</strong>, regenerated monthly by GitHub Actions covering ~18 months ahead, served as static files from GitHub Pages (<code>webcal://</code> subscriptions, zero hosting cost).</p><pre class="mermaid">flowchart LR
    CRON[&quot;GitHub Actions&lt;br/&gt;(monthly cron)&quot;] --&gt; GEN[&quot;python -m telugu_panchangam.generate&quot;]
    GEN --&gt;|&quot;22 cities × 3 systems&quot;| ICS[&quot;66 × .ics&quot;]
    ICS --&gt; PAGES[&quot;GitHub Pages&lt;br/&gt;panchangam.astrochaganti.com&quot;]
    PAGES --&gt;|&quot;webcal://&quot;| SUB[&quot;Google / Apple / Outlook&quot;]
</pre><p><strong>Cities:</strong> Telugu heartland (Hyderabad, Vijayawada, Visakhapatnam, Tirupati, Warangal, Guntur, Nizamabad, Rajahmundry, Kurnool, Nellore) · metros (Bengaluru, Chennai, Mumbai, Delhi) · diaspora (Dallas, San Jose, San Francisco, Edison, New York, London, Sydney, Dubai).</p><p><strong>Systems:</strong> Drik Ganita (modern apps) · Surya Siddhanta (classical tradition) · Vakya (Telugu/Tamil printed panchangams).</p><hr><h2 id="_3-landing-page" tabindex="-1">3. Landing page <a class="header-anchor" href="#_3-landing-page" aria-label="Permalink to &quot;3. Landing page&quot;">​</a></h2><p>The Vite/TypeScript application under <code>src/</code>, built by <code>deploy-landing.yml</code> and served at <code>panchangam.astrochaganti.com</code> (the <code>CNAME</code> is load-bearing — never drop it). Beyond letting devotees pick a city/system and copy a <code>webcal://</code> URL, it&#39;s a daily toolkit:</p><ul><li><strong>Today&#39;s Panchangam</strong> — any date, any city.</li><li><strong>Tarabalam · Muhurtam</strong> — good days &amp; ranked time slots for up to four people by birth star, with Chandrabalam. Typed scorer modules consume the generated Python activity contract; runtime <code>lagna.json</code> / <code>gochara.json</code> sidecars supply slot-time data. The per-city Lagna sidecar also carries Guru/Shukra combustion flags, allowing browser Muhurtam searches to enforce the same Maudhya exclusions declared by the Python activity profile. If those flags are absent, affected browser searches fail closed instead of returning unscreened dates.</li><li><strong>Gochara + Rasi Phalalu</strong> — South Indian chart, transit verdicts, computed daily reading.</li></ul><p>Everything is shareable to WhatsApp.</p><blockquote><p>MCP remains the complete computational interface. The website intentionally presents a curated devotee-facing subset; its declared activity catalogue and generated rule contract are protected by parity tests.</p></blockquote>`,35)])])}const p=t(s,[["render",d]]);export{u as __pageData,p as default};
